const { sortByTransactionId } = require("../utils/sort");

const STATUS_ORDER = { pending: 0, approved: 1, rejected: 2, reversed: 3 };

function maxStatus(a, b) {
  const aa = STATUS_ORDER[String(a || "pending").toLowerCase()] ?? 0;
  const bb = STATUS_ORDER[String(b || "pending").toLowerCase()] ?? 0;
  return aa >= bb ? String(a || "pending").toLowerCase() : String(b || "pending").toLowerCase();
}

function joinReasons(reasons) {
  const uniq = [...new Set(reasons.filter(Boolean))].sort();
  return uniq.length ? uniq.join(";") : null;
}

function reconcileTransactions(parsed) {
  // 1) Canonical ledger row selection.
  // Prefer a non-provisional row; if multiple candidates exist, take the last occurrence.
  const ledgerById = new Map();
  for (const row of parsed.ledger) {
    const id = row.transaction_id;
    const existing = ledgerById.get(id);
    const candidate = { ...row, provisional: Boolean(row.provisional) };
    if (!existing) {
      ledgerById.set(id, candidate);
      continue;
    }
    // If existing is provisional and candidate is not, upgrade.
    if (existing.provisional && !candidate.provisional) {
      ledgerById.set(id, candidate);
      continue;
    }
    // If both same provisional-ness, keep the later row (last-write-wins).
    if (existing.provisional === candidate.provisional) {
      ledgerById.set(id, candidate);
    }
  }

  // Pre-correction effective date baseline for compliance_hold comparisons (Brief 09).
  const baselineEffectiveDate = new Map(
    [...ledgerById.entries()].map(([id, row]) => [id, row.date]),
  );

  // 2) Apply signed meeting owner amendments.
  // (Brief 05 indicates unsigned amendments should not override.)
  for (const meeting of [...parsed.meetings].sort((a, b) => (a.transaction_id < b.transaction_id ? -1 : 1))) {
    if (!meeting.signed) continue;
    const target = ledgerById.get(meeting.transaction_id);
    if (target && meeting.owner) target.owner = meeting.owner;
  }

  // 3) Apply mail-driven status changes with precedence.
  // Keep deterministic order: by (date, from_addr, transaction_id).
  const emails = [...parsed.emails].sort((a, b) => {
    const ad = a.date || "";
    const bd = b.date || "";
    if (ad !== bd) return ad < bd ? -1 : 1;
    if (a.from_addr !== b.from_addr) return a.from_addr < b.from_addr ? -1 : 1;
    if (a.transaction_id !== b.transaction_id) return a.transaction_id < b.transaction_id ? -1 : 1;
    if (a.status !== b.status) return a.status < b.status ? -1 : 1;
    return 0;
  });

  for (const email of emails) {
    const target = ledgerById.get(email.transaction_id);
    if (!target) continue;
    // Minimal authorization gate: only accept mail from compliance desk.
    // (Archive language refers to "compliance desk"; without a stricter rule provided here,
    // require sender contains 'compliance'.)
    if (!String(email.from_addr).toLowerCase().includes("compliance")) continue;
    target.status = maxStatus(target.status, email.status);
  }

  // 4) Apply correction notices.
  // Deterministic order; report previous_value must reflect value immediately before applying.
  const report = [];
  const notices = [...parsed.corrections].sort((a, b) => {
    if (a.notice_id === b.notice_id) return 0;
    return a.notice_id < b.notice_id ? -1 : 1;
  });

  for (const notice of notices) {
    const target = ledgerById.get(notice.transaction_id);
    if (!target) continue;

    let previous;
    if (notice.field === "owner") {
      previous = target.owner ?? "";
      target.owner = notice.value;
    } else if (notice.field === "status") {
      previous = String(target.status ?? "");
      target.status = notice.value;
    } else if (notice.field === "date") {
      previous = String(target.date ?? "");
      target.date = notice.value;
    } else {
      continue;
    }

    report.push({
      notice_id: notice.notice_id,
      transaction_id: notice.transaction_id,
      field: notice.field,
      previous_value: String(previous),
      new_value: String(notice.value),
      effective: String(notice.effective || ""),
    });
  }

  // 5) Build output items and exception flags.
  const items = sortByTransactionId(
    [...ledgerById.values()].map((row) => {
      const reasons = [];

      if (parsed.policyExceptions && parsed.policyExceptions.has(row.transaction_id)) {
        reasons.push("policy_exception");
      }

      // compliance_hold: email timing check per Brief 09 baseline effective date (pre-correction).
      const baseline = baselineEffectiveDate.get(row.transaction_id);
      if (baseline) {
        const hasLateComplianceMail = emails.some(
          (e) =>
            e.transaction_id === row.transaction_id &&
            e.date &&
            String(e.from_addr).toLowerCase().includes("compliance") &&
            e.date > baseline,
        );
        if (hasLateComplianceMail) reasons.push("compliance_hold");
      }

      return {
        transaction_id: row.transaction_id,
        owner: row.owner,
        status: String(row.status).toLowerCase(),
        effective_date: row.date,
        amount_usd: Number(row.amount),
        exception_reason: joinReasons(reasons),
      };
    }),
  );

  return { items, report };
}

